/*
 * services/ride_records_core (D-098) against vehicle-server's golden ride records
 * (vectors/derived_ride_records.h, generated by vehicle-server's float32 encoder, the same
 * arithmetic as this writer: the ties 2.5 -> 2 and 3.5 -> 4 are exact float32 values):
 * 1. derived_ride_field_vectors: every generic-writer case, bit-exact (473 rows).
 * 2. derived_no_ride_records: the no-ride encoding of every served record, byte-exact.
 * 3. derived_<scenario>_ride_records: the writer fed the expected closed values of each
 *    class-B scenario ride (counter = ride + 1) gives the expected record, byte-exact.
 * 4. The gen/ layout as this writer reads it: every field inside its record, headers, copy.
 */
#include "services/ride_records_core.h"
#include "vectors/derived_accel_gears_b.h"
#include "vectors/derived_edge_values_b.h"
#include "vectors/derived_idle_warmup_b.h"
#include "vectors/derived_ride_records.h"
#include "vectors/derived_stale_gap_b.h"
#include "vectors/derived_two_rides_b.h"

#include <math.h>
#include <stdio.h>
#include <string.h>
#include <unity.h>

_Static_assert(DERIVED_RIDE_FIELD_COUNT == PLATFORM_UDS_RIDE_FIELD_COUNT, "golden rows = gen/ rows");
_Static_assert(DERIVED_RIDE_RECORD_LAYOUT_VERSION == PLATFORM_UDS_RIDE_RECORD_LAYOUT_VERSION,
               "golden layout version = gen/");

void setUp(void) {}
void tearDown(void) {}

static uint8_t buf[RIDE_RECORDS_BYTES];

static uint32_t did_index(uint16_t did)
{
    for (uint32_t i = 0u; i < PLATFORM_UDS_DID_COUNT; i++) {
        if (platform_uds_dids[i].did == did) {
            return i;
        }
    }
    return PLATFORM_UDS_DID_COUNT;
}

/* ---- 1. generic writer -------------------------------------------------------------------- */

static void test_every_golden_field_vector_is_bit_exact(void)
{
    TEST_ASSERT_EQUAL_UINT32(DERIVED_RIDE_FIELD_VECTOR_COUNT,
                             (uint32_t)(sizeof derived_ride_field_vectors / sizeof derived_ride_field_vectors[0]));
    uint32_t bad = 0u;
    for (uint32_t i = 0u; i < DERIVED_RIDE_FIELD_VECTOR_COUNT; i++) {
        const derived_ride_field_vector_t* const v = &derived_ride_field_vectors[i];
        TEST_ASSERT_TRUE(v->field < PLATFORM_UDS_RIDE_FIELD_COUNT);
        const uint32_t raw =
            ride_records_field_raw(&platform_uds_ride_fields[v->field], v->has_value, v->value);
        if (raw != v->raw) {
            fprintf(stderr, "vector %u field %u value %.9g: expected %u, got %u\n", (unsigned)i,
                    (unsigned)v->field, (double)v->value, (unsigned)v->raw, (unsigned)raw);
            bad++;
        }
    }
    TEST_ASSERT_EQUAL_UINT32(0u, bad);
}

static void test_not_finite_and_far_values_are_not_available(void)
{
    const platform_uds_ride_field_t* const f = &platform_uds_ride_fields[0];
    TEST_ASSERT_EQUAL_UINT32(f->na, ride_records_field_raw(f, true, NAN));
    TEST_ASSERT_EQUAL_UINT32(f->na, ride_records_field_raw(f, true, INFINITY));
    TEST_ASSERT_EQUAL_UINT32(f->na, ride_records_field_raw(f, true, -INFINITY));
    TEST_ASSERT_EQUAL_UINT32(f->na, ride_records_field_raw(f, true, 3.0e38f)); /* never clamped */
    TEST_ASSERT_EQUAL_UINT32(f->na, ride_records_field_raw(f, true, -3.0e38f));
    TEST_ASSERT_EQUAL_UINT32(0u, ride_records_field_raw(NULL, true, 1.0f));
    for (uint32_t i = 0u; i < PLATFORM_UDS_RIDE_FIELD_COUNT; i++) {
        const platform_uds_ride_field_t* const g = &platform_uds_ride_fields[i];
        TEST_ASSERT_EQUAL_UINT32(g->na, ride_records_field_raw(g, false, g->range_min));
        TEST_ASSERT_EQUAL_UINT32(0u, ride_records_field_raw(g, true, g->range_min));
    }
}

/* ---- 2. no ride --------------------------------------------------------------------------- */

static void assert_record(uint16_t did, uint8_t length, const uint8_t* bytes)
{
    const uint32_t idx = did_index(did);
    TEST_ASSERT_TRUE(idx < PLATFORM_UDS_DID_COUNT);
    TEST_ASSERT_TRUE(ride_records_is_record(idx));
    TEST_ASSERT_EQUAL_UINT8(platform_uds_dids[idx].length, length);
    uint8_t rec[DERIVED_RIDE_RECORD_MAX_LENGTH];
    TEST_ASSERT_TRUE(ride_records_copy(buf, idx, rec, length));
    TEST_ASSERT_EQUAL_HEX8_ARRAY(bytes, rec, length);
}

static void test_the_no_ride_records_match_the_golden_ones(void)
{
    const uint32_t n = (uint32_t)(sizeof derived_no_ride_records / sizeof derived_no_ride_records[0]);
    TEST_ASSERT_EQUAL_UINT32(DERIVED_RIDE_RECORD_COUNT, n);
    (void)memset(buf, 0xA5, sizeof buf);
    ride_records_encode(NULL, false, 0u, buf);
    uint32_t total = 0u;
    for (uint32_t i = 0u; i < n; i++) {
        assert_record(derived_no_ride_records[i].did, derived_no_ride_records[i].length,
                      derived_no_ride_records[i].bytes);
        total += derived_no_ride_records[i].length;
    }
    TEST_ASSERT_EQUAL_UINT32(RIDE_RECORDS_BYTES, total); /* the golden set is the served set */
    /* closed with no value source, or not closed with a counter: still the no-ride records */
    uint8_t other[RIDE_RECORDS_BYTES];
    ride_records_encode(NULL, true, 7u, other);
    TEST_ASSERT_EQUAL_HEX8_ARRAY(buf, other, sizeof buf);
    ride_records_encode(NULL, false, 7u, other);
    TEST_ASSERT_EQUAL_HEX8_ARRAY(buf, other, sizeof buf);
    ride_records_encode(NULL, false, 0u, NULL); /* no-op */
}

/* ---- 3. scenario records ------------------------------------------------------------------ */

typedef struct {
    const char* name;
    const derived_vector_b_output_t* out;
    uint32_t n_out;
    const derived_ride_record_expected_t* rec;
    uint32_t n_rec;
    uint32_t n_rides;
} rscenario_t;

#define RSCENARIO(n, N)                                                                   \
    { #n, n##_b_outputs, N##_B_OUTPUT_COUNT, n##_ride_records, N##_RIDE_RECORD_COUNT, N##_RIDE_COUNT }

static const rscenario_t rscenarios[] = {
    RSCENARIO(derived_idle_warmup, DERIVED_IDLE_WARMUP), RSCENARIO(derived_accel_gears, DERIVED_ACCEL_GEARS),
    RSCENARIO(derived_stale_gap, DERIVED_STALE_GAP),     RSCENARIO(derived_edge_values, DERIVED_EDGE_VALUES),
    RSCENARIO(derived_two_rides, DERIVED_TWO_RIDES),
};

static const rscenario_t* cur_sc;
static uint16_t cur_ride;

static bool expected_value(uint32_t signal, float* value)
{
    for (uint32_t i = 0u; i < cur_sc->n_out; i++) {
        const derived_vector_b_output_t* const e = &cur_sc->out[i];
        if ((e->ride == cur_ride) && (e->signal == signal) && e->valid) {
            *value = e->value;
            return true;
        }
    }
    return false;
}

static void test_the_scenario_records_match_the_golden_ones(void)
{
    uint32_t checked = 0u;
    for (uint32_t s = 0u; s < sizeof rscenarios / sizeof rscenarios[0]; s++) {
        cur_sc = &rscenarios[s];
        TEST_ASSERT_EQUAL_UINT32(cur_sc->n_rides * DERIVED_RIDE_RECORD_COUNT, cur_sc->n_rec);
        for (uint16_t ride = 0u; ride < cur_sc->n_rides; ride++) {
            cur_ride = ride;
            ride_records_encode(expected_value, true, (uint16_t)(ride + 1u), buf);
            for (uint32_t r = 0u; r < cur_sc->n_rec; r++) {
                if (cur_sc->rec[r].ride == ride) {
                    assert_record(cur_sc->rec[r].did, cur_sc->rec[r].length, cur_sc->rec[r].bytes);
                    checked++;
                }
            }
        }
    }
    TEST_ASSERT_EQUAL_UINT32(6u * DERIVED_RIDE_RECORD_COUNT, checked); /* 4 + 2 rides */
}

/* ---- 4. layout ---------------------------------------------------------------------------- */

static void test_every_field_lies_inside_a_served_record_after_the_header(void)
{
    for (uint32_t i = 0u; i < PLATFORM_UDS_RIDE_FIELD_COUNT; i++) {
        const platform_uds_ride_field_t* const f = &platform_uds_ride_fields[i];
        TEST_ASSERT_TRUE(ride_records_is_record(f->did_idx));
        TEST_ASSERT_TRUE(f->byte >= 4u); /* after the D-098 4-byte header */
        TEST_ASSERT_TRUE((uint32_t)f->byte + f->length <= platform_uds_dids[f->did_idx].length);
        TEST_ASSERT_TRUE((f->length == 1u) || (f->length == 2u) || (f->length == 4u));
        TEST_ASSERT_TRUE(f->raw_max < f->na);
    }
    uint32_t served = 0u;
    for (uint32_t i = 0u; i < PLATFORM_UDS_DID_COUNT; i++) {
        if (ride_records_is_record(i)) {
            TEST_ASSERT_EQUAL_UINT8(PLATFORM_UDS_ENC_RECORD, platform_uds_dids[i].encoding);
            uint8_t rec[PLATFORM_UDS_MAX_DID_LENGTH];
            ride_records_encode(NULL, false, 0u, buf); /* the writer's record length = gen/ table */
            TEST_ASSERT_TRUE(ride_records_copy(buf, i, rec, platform_uds_dids[i].length));
            served++;
        }
    }
    TEST_ASSERT_EQUAL_UINT32(DERIVED_RIDE_RECORD_COUNT, served);
    TEST_ASSERT_FALSE(ride_records_is_record(PLATFORM_UDS_IDX_LEAN_HEALTH));
    TEST_ASSERT_FALSE(ride_records_is_record(PLATFORM_UDS_DID_COUNT));
}

static void test_the_header_carries_the_counter_and_the_closed_flag(void)
{
    cur_sc = &rscenarios[0];
    cur_ride = 0u;
    ride_records_encode(expected_value, true, 0xFFFFu, buf); /* the header is exempt from NA */
    uint8_t rec[PLATFORM_UDS_DID_RIDE_USAGE_LENGTH];
    TEST_ASSERT_TRUE(ride_records_copy(buf, PLATFORM_UDS_IDX_RIDE_USAGE, rec, sizeof rec));
    TEST_ASSERT_EQUAL_HEX8(PLATFORM_UDS_RIDE_RECORD_LAYOUT_VERSION, rec[PLATFORM_UDS_RIDE_USAGE_LAYOUT_VERSION_BYTE]);
    TEST_ASSERT_EQUAL_HEX8(0xFFu, rec[PLATFORM_UDS_RIDE_USAGE_RIDE_COUNTER_BYTE]);
    TEST_ASSERT_EQUAL_HEX8(0xFFu, rec[PLATFORM_UDS_RIDE_USAGE_RIDE_COUNTER_BYTE + 1u]);
    TEST_ASSERT_EQUAL_HEX8(PLATFORM_UDS_RIDE_USAGE_RIDE_CLOSED_MASK, rec[PLATFORM_UDS_RIDE_USAGE_RIDE_CLOSED_BYTE]);
    TEST_ASSERT_EQUAL_HEX8(0u, rec[PLATFORM_UDS_RIDE_USAGE_RESERVED_BYTE] & PLATFORM_UDS_RIDE_USAGE_RESERVED_MASK);
    ride_records_encode(expected_value, true, 0x1234u, buf);
    TEST_ASSERT_TRUE(ride_records_copy(buf, PLATFORM_UDS_IDX_RIDE_USAGE, rec, sizeof rec));
    TEST_ASSERT_EQUAL_HEX8(0x12u, rec[PLATFORM_UDS_RIDE_USAGE_RIDE_COUNTER_BYTE]); /* big-endian */
    TEST_ASSERT_EQUAL_HEX8(0x34u, rec[PLATFORM_UDS_RIDE_USAGE_RIDE_COUNTER_BYTE + 1u]);
}

static void test_copy_refuses_a_wrong_length_or_index(void)
{
    ride_records_encode(NULL, false, 0u, buf);
    uint8_t rec[DERIVED_RIDE_RECORD_MAX_LENGTH + 1u];
    TEST_ASSERT_FALSE(ride_records_copy(buf, PLATFORM_UDS_IDX_RIDE_USAGE, rec, PLATFORM_UDS_DID_RIDE_USAGE_LENGTH - 1u));
    TEST_ASSERT_FALSE(ride_records_copy(buf, PLATFORM_UDS_IDX_RIDE_USAGE, rec, PLATFORM_UDS_DID_RIDE_USAGE_LENGTH + 1u));
    TEST_ASSERT_FALSE(ride_records_copy(buf, PLATFORM_UDS_IDX_UPTIME, rec, PLATFORM_UDS_DID_RIDE_USAGE_LENGTH));
    TEST_ASSERT_FALSE(ride_records_copy(NULL, PLATFORM_UDS_IDX_RIDE_USAGE, rec, PLATFORM_UDS_DID_RIDE_USAGE_LENGTH));
    TEST_ASSERT_FALSE(ride_records_copy(buf, PLATFORM_UDS_IDX_RIDE_USAGE, NULL, PLATFORM_UDS_DID_RIDE_USAGE_LENGTH));
    TEST_ASSERT_TRUE(ride_records_copy(buf, PLATFORM_UDS_IDX_RIDE_WINDOW_POST_STOP, rec,
                                       PLATFORM_UDS_DID_RIDE_WINDOW_POST_STOP_LENGTH));
}

int main(void)
{
    UNITY_BEGIN();
    RUN_TEST(test_every_golden_field_vector_is_bit_exact);
    RUN_TEST(test_not_finite_and_far_values_are_not_available);
    RUN_TEST(test_the_no_ride_records_match_the_golden_ones);
    RUN_TEST(test_the_scenario_records_match_the_golden_ones);
    RUN_TEST(test_every_field_lies_inside_a_served_record_after_the_header);
    RUN_TEST(test_the_header_carries_the_counter_and_the_closed_flag);
    RUN_TEST(test_copy_refuses_a_wrong_length_or_index);
    return UNITY_END();
}
